public class MovingAverager {

    public static double[] movingAverage(int[] a, int window) {
        int count = a.length - window + 1;
        double[] result = new double[count];
        for (int start = 0; start < count; start++) {
            int sum = 0;
            for (int i = start; i < start + window; i++) {
                sum += a[i];
            }
            result[start] = (double) sum / window;
        }
        return result;
    }
}
